"use client";
/* Penguin, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Penguin(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("penguin"); }, []);
  return React.createElement("piix-pal", { "pal": "penguin", ...piixAttrs(props) });
}

export default Penguin;
